function validate(input) {
  const [{ SurveyLog = [] }] = input;
  const seen = new Set(), shown = new Set();
  for (const [id, action, question, answer] of SurveyLog) {
    if (id === null || question === null) return 'id and question_id cannot be null.';
    if (!['show', 'answer', 'skip'].includes(action)) return `Unknown action ${action}.`;
    if ((action === 'answer') !== (answer !== null)) return 'answer_id must be set on answer rows and only there.';
    seen.add(question);
    if (action === 'show') shown.add(question);
  }
  for (const question of seen) if (!shown.has(question)) return `Question ${question} is never shown.`;
  return null;
}

