function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const small = size === 'small';
  const questions = small ? [285, 369, 7, 12] : Array.from({ length: 300 }, (_, i) => i + 1);
  const users = small ? [1, 2, 5] : Array.from({ length: 50 }, (_, i) => i + 1);
  const limit = small ? Math.floor(rand() * 9) : 1990;
  // Answer odds differ per question so rates spread out; small cases also hit exact ties.
  const odds = new Map(questions.map(q => [q, pick([0, 0.3, 0.5, 0.8, 1])]));
  const SurveyLog = [], session = new Map();
  let time = 100;
  const push = row => { if (SurveyLog.length < limit) SurveyLog.push(row); };
  while (SurveyLog.length < limit) {
    const user = pick(users), question = pick(questions);
    const q = (session.get(user) ?? 0) + 1;
    session.set(user, q);
    push([user, 'show', question, null, q, time++]);
    const r = rand();
    if (r < odds.get(question)) push([user, 'answer', question, 1000 + Math.floor(rand() * 9000), q, time++]);
    else if (r < 0.9) push([user, 'skip', question, null, q, time++]);
    // Logs may repeat a row exactly; the repeat counts as another action.
    if (rand() < 0.1 && SurveyLog.length) push([...SurveyLog[SurveyLog.length - 1]]);
  }
  return [{ SurveyLog }];
}
